module parity_8bit (
    input [7:0] in,
    output out
);
    assign out = ^in;
endmodule

module mux4to1 (
    input [3:0] in,
    input [1:0] sel,
    output out
);

    wire not_sel0, not_sel1;
    wire and0, and1, and2, and3;

    not(not_sel0, sel[0]);
    not(not_sel1, sel[1]);

    and(and0, in[0], not_sel1, not_sel0);
    and(and1, in[1], not_sel1, sel[0]);
    and(and2, in[2], sel[1], not_sel0);
    and(and3, in[3], sel[1], sel[0]);

    or(out, and0, and1, and2, and3);

endmodule

module majority (
    input a, b, c,
    output out
);
