endmodule

module fsm_3state (
    input clk,
    input reset,
    output reg [1:0] state
);

always @(posedge clk) begin
    if (reset)
        state <= 2'b00;
    else
        state <= (state == 2'b10) ? 2'b00 : state + 1;
end

endmodule

module traffic_light (
    input clk, reset,
    output [2:0] light
);

    // State encoding
    parameter RED    = 2'b00;
    parameter YELLOW = 2'b01;
    parameter GREEN  = 2'b10;

    reg [1:0] state;

    // State register with synchronous reset (active high)
    always @(posedge clk) begin
        if (reset)
            state <= RED;
        else begin
            case (state)
                RED:    state <= GREEN;
                GREEN:  state <= YELLOW;
                YELLOW: state <= RED;
                default: state <= RED;
            endcase
        end
    end

    // Output encoding: [2]=RED, [1]=YELLOW, [0]=GREEN
    assign light = (state == RED)    ? 3'b100 :
                   (state == YELLOW) ? 3'b010 :
                   (state == GREEN)  ? 3'b001 :
                                       3'b100;

endmodule

module elevator_controller (
    input clk, reset,
    input up_request, down_request,
    output [1:0] state
);

    parameter IDLE = 2'b00;
    parameter MOVING_UP = 2'b01;
    parameter MOVING_DOWN = 2'b10;

    reg [1:0] current_state, next_state;

    always @(posedge clk or posedge reset) begin
        if (reset)
            current_state <= IDLE;
        else
            current_state <= next_state;
    end

    always @(*) begin
        case (current_state)
            IDLE: begin
                if (up_request)
                    next_state = MOVING_UP;
                else if (down_request)
                    next_state = MOVING_DOWN;
                else
                    next_state = IDLE;
            end
            MOVING_UP: begin
                if (up_request)
                    next_state = MOVING_UP;
                else
                    next_state = IDLE;
            end
            MOVING_DOWN: begin
                if (down_request)
                    next_state = MOVING_DOWN;
                else
                    next_state = IDLE;
            end
            default: next_state = IDLE;
        endcase
    end

    assign state = current_state;

endmodule

module vending_machine (
    input clk, reset,
    input coin_inserted, item_selected,
    output [1:0] state
);

    // State definitions
    localparam [1:0] IDLE = 2'b00;
    localparam [1:0] COLLECTING_COINS = 2'b01;
    localparam [1:0] DISPENSING_ITEM = 2'b10;

    // Internal state register
    reg [1:0] state_reg, state_next;

    // State register update
    always @(posedge clk or posedge reset) begin
        if (reset)
            state_reg <= IDLE;
        else
            state_reg <= state_next;
    end

    // Next state logic
    always @(*) begin
        state_next = state_reg; // default: stay in current state

        case (state_reg)
            IDLE: begin
                if (coin_inserted)
                    state_next = COLLECTING_COINS;
            end

            COLLECTING_COINS: begin
                if (item_selected)
                    state_next = DISPENSING_ITEM;
                else if (!coin_inserted)
                    state_next = IDLE;
            end

            DISPENSING_ITEM: begin
                state_next = IDLE;
            end

            default: state_next = IDLE;
        endcase
    end

    // Output assignment
    assign state = state_reg;

endmodule

