module feistel_cipher(
    input  [7:0] data_in,
    output [7:0] data_out
);

    // Split input into left and right 4-bit halves
    wire [3:0] L0 = data_in[7:4];
    wire [3:0] R0 = data_in[3:0];

    // Simple round function: XOR with fixed 4-bit key
    wire [3:0] ROUND_KEY = 4'b1010;
    wire [3:0] F_out = R0 ^ ROUND_KEY;

    // Single Feistel round
    wire [3:0] L1 = R0;
    wire [3:0] R1 = L0 ^ F_out;

    // Swap halves after encryption and form output
    assign data_out = {R1, L1};

endmodule

module clock_div2 (
