    output clk_out
);

reg clk_div_reg;

always @(posedge clk) begin
    if (rst)
        clk_div_reg <= 1'b0;
    else
        clk_div_reg <= ~clk_div_reg;
end

assign clk_out = clk_div_reg;

endmodule

module comparator_4bit(input [3:0] a, input [3:0] b, output gt, eq, lt);

