endmodule

module decoder_2to4 (
    input  [1:0] in,
    input        enable,
    output [3:0] out
);

wire n0, n1;

not (n0, in[0]);
not (n1, in[1]);

and (out[0], enable, n1, n0);
and (out[1], enable, n1, in[0]);
and (out[2], enable, in[1], n0);
and (out[3], enable, in[1], in[0]);

endmodule

module decoder2to4(input [1:0] in, input enable, output [3:0] out);
    assign out[0] = enable & (~in[1]) & (~in[0]);
    assign out[1] = enable & (~in[1]) & in[0];
    assign out[2] = enable & in[1] & (~in[0]);
    assign out[3] = enable & in[1] & in[0];
endmodule

module decoder3to8(input [2:0] in, input enable, output [7:0] out);
    wire [3:0] decoder_out_low;
    wire [3:0] decoder_out_high;
    wire enable_low, enable_high;

    decoder2to4 low_decoder(.in(in[1:0]), .enable(enable_low), .out(decoder_out_low));
    decoder2to4 high_decoder(.in(in[1:0]), .enable(enable_high), .out(decoder_out_high));

    assign enable_low = enable & (~in[2]);
    assign enable_high = enable & in[2];

    assign out[3:0] = decoder_out_low;
    assign out[7:4] = decoder_out_high;
endmodule

module demux_1to2 (
    input  in,
    input  sel,
    output out0,
    output out1
);

assign out0 = in & (~sel);
assign out1 = in & sel;

endmodule

module demux_1to2 (
    input  in,
    input  sel,
    output out0,
    output out1
);
    assign out0 = (sel == 1'b0) ? in : 1'b0;
    assign out1 = (sel == 1'b1) ? in : 1'b0;
endmodule

module demux_1to4 (
    input        in,
    input  [1:0] sel,
    output       out0,
    output       out1,
    output       out2,
    output       out3
);
    wire stage0_out0, stage0_out1;

    demux_1to2 stage0 (
        .in   (in),
        .sel  (sel[1]),
        .out0 (stage0_out0),
        .out1 (stage0_out1)
    );

    demux_1to2 stage1 (
        .in   (stage0_out0),
        .sel  (sel[0]),
        .out0 (out0),
        .out1 (out1)
    );

    demux_1to2 stage2 (
        .in   (stage0_out1),
        .sel  (sel[0]),
        .out0 (out2),
        .out1 (out3)
    );
endmodule

module gray_counter8(
    input wire clk,
    input wire rst,
    output wire [7:0] count
);

    reg [7:0] binary_count;

    always @(posedge clk) begin
        if (rst)
            binary_count <= 8'b0;
        else
            binary_count <= binary_count + 1'b1;
    end

    assign count = binary_count ^ (binary_count >> 1);

endmodule

