module TopModule (
  input clk,
  input resetn,
  input  [2:0] r,
  output [2:0] g
);
    localparam A = 0, B = 1, C = 2, D = 3;
  reg [1:0] state, next;

  always @(posedge clk) begin
    if (~resetn) state <= A;
    else state <= next;
  end

  always @(*) begin
    case (state)
      A: next = r[0] ? B : (r[1] ? C : (r[2] ? D : A));
      B: next = r[0] ? B : A;
      C: next = r[1] ? C : A;
      D: next = r[2] ? D : A;
    endcase
  end

  assign g = (state == A ? 0 : state == B ? 1 << 0 : state == C ? 1 << 1 : 1 << 2);
endmodule

module TopModule (
  input clk,
  input w,
  input R,
  input E,
  input L,
  output reg Q
);
    wire next_q;

  // Determine next state logic
  assign next_q = (L) ? R : (E) ? w : Q;

  // Sequential logic
  always @(posedge clk) begin
    Q <= next_q;
  end
endmodule

module TopModule (
    input p1a, p1b, p1c, p1d,
    output p1y,
    input p2a, p2b, p2c, p2d,
    output p2y
);

    // First 4-input NAND gate for p1y
    assign p1y = ~(p1a & p1b & p1c & p1d);

    // Second 4-input NAND gate for p2y
    assign p2y = ~(p2a & p2b & p2c & p2d);

endmodule

module TopModule (
    input p1a, p1b, p1c, p1d, p1e, p1f,
    output p1y,
    input p2a, p2b, p2c, p2d,
    output p2y
);
    // Declare wires for the AND gate outputs
    wire and1, and2, and3, and4;

    // First AND gates for p1y (3-input each)
    assign and1 = p1a & p1b & p1c;
    assign and2 = p1d & p1e & p1f;

    // OR gates for p1y
    assign p1y = and1 | and2;

    // Second AND gates for p2y (2-input each)
    assign and3 = p2a & p2b;
    assign and4 = p2c & p2d;

    // OR gates for p2y
    assign p2y = and3 | and4;
endmodule

module TopModule (
