module TopModule (
  input clk,
  input a,
  input b,
  output out_assign,
  output reg out_always_comb,
  output reg out_always_ff
);
    // XOR gate implemented with an assign statement
  assign out_assign = a ^ b;

  // Combinational always block
  always_comb begin
    out_always_comb = a ^ b;
  end

  // Clocked always block with flip-flop
  always_ff @(posedge clk) begin
    out_always_ff <= a ^ b;
  end
endmodule

