module TopModule (
  input clk,
  input areset,
  input train_valid,
  input train_taken,
  output logic [1:0] state
);
    always_ff @(posedge clk or posedge areset) begin
    if (areset)
      state <= 2'b01;
    else if (train_valid && train_taken)
      state <= (state < 2'b11) ? state + 2'b01 : 2'b11;
    else if (train_valid)
      state <= (state > 2'b00) ? state - 2'b01 : 2'b00;
  end
endmodule

