module TopModule (
  input clk,
  input enable,
  input S,
  input A,
  input B,
  input C,
  output reg Z
);
    reg [7:0] Q;
  wire [2:0] index;

  // Shift register logic
  always @(posedge clk) begin
    if (enable)
      Q <= {Q[6:0], S};
  end

  // Multiplexer to select Q[index]
  assign index = {A, B, C};
  assign Z = Q[index];
endmodule

module TopModule (
  input clk,
  input j,
  input k,
  output reg Q
);

  // JK flip-flop implemented using the characteristic equation:
  // Q_next = J * ~Q_old + ~K * Q_old
  always @(posedge clk) begin
    Q <= (j & ~Q) | (~k & Q);
  end

endmodule

module TopModule (
  input clk,
  input aresetn,
  input x,
  output reg z
);

  reg [1:0] current_state, next_state;
  localparam S0 = 2'b00,
             S1 = 2'b01,
             S2 = 2'b10;

  // State register
  always @(posedge clk or negedge aresetn) begin
    if (!aresetn)
      current_state <= S0;
    else
      current_state <= next_state;
  end

  // Next state logic
  always @(*) begin
    case (current_state)
      S0: next_state = x ? S1 : S0;
      S1: next_state = x ? S1 : S2;
      S2: next_state = x ? S1 : S0;
      default: next_state = S0;
    endcase
  end

  // Output logic (Mealy)
  always @(*) begin
    z = (current_state == S2) && x;
  end

endmodule

module TopModule (
