module TopModule (
  input clk,
  input in,
  input areset,
  output out
);
  reg state;

  // Asynchronous reset to state B (output = 1)
  always @(posedge clk or posedge areset) begin
    if (areset)
      state <= 1'b1;          // B
    else
      state <= in ? state : ~state; // toggle on in=0, stay on in=1
