module TopModule (
  input clk,
  input j,
  input k,
  input reset,
  output out
);

  // State encoding
  localparam OFF = 1'b0;
  localparam ON  = 1'b1;

  reg state;
  wire next_state;

  // Moore output depends only on state
  assign out = state;

  // Next-state logic
  assign next_state = (state == OFF) ? (j ? ON : OFF)
                                     : (k ? OFF : ON);

  // Synchronous state register with active-high synchronous reset
  always @(posedge clk) begin
    if (reset)
      state <= OFF;
    else
      state <= next_state;
  end

endmodule

module TopModule (
  input clk,
  input in,
  input reset,
  output out
);

  // State encoding
  parameter A = 2'b00;
  parameter B = 2'b01;
  parameter C = 2'b10;
  parameter D = 2'b11;

  // State register
  reg [1:0] state;

  // State transition logic
  always @(posedge clk) begin
    if (reset) begin
      state <= A;
    end else begin
      case (state)
        A: state <= in ? B : A;
        B: state <= in ? B : C;
        C: state <= in ? D : A;
        D: state <= in ? B : C;
        default: state <= A;
      endcase
    end
  end

  // Output logic
  assign out = (state == D);

endmodule

