module TopModule (
    input clk,
    input reset,
    input w,
    output z
);

    parameter A = 3'd0,
              B = 3'd1,
              C = 3'd2,
              D = 3'd3,
              E = 3'd4,
              F = 3'd5;

    reg [2:0] current_state, next_state;

    // State flip-flops (sequential logic)
    always @(posedge clk) begin
        if (reset)
            current_state <= A;
        else
            current_state <= next_state;
    end

    // Next state logic (state table)
    always @* begin
        case (current_state)
            A: next_state = w ? B : A;
            B: next_state = w ? C : D;
            C: next_state = w ? E : D;
            D: next_state = w ? F : A;
            E: next_state = w ? E : D;
            F: next_state = w ? C : D;
            default: next_state = A;
        endcase
    end

    // Output logic (MSB of state code)
    assign z = current_state[2];

endmodule

