            3'b010: Y_next = x ? 3'b001 : 3'b010;
            3'b011: Y_next = x ? 3'b010 : 3'b001;
            3'b100: Y_next = x ? 3'b100 : 3'b011;
            default: Y_next = 3'b000;
        endcase
        Y0 = Y_next[0];
        z  = (y == 3'b011) || (y == 3'b100);
    end
endmodule

