  assign next_state[0] = state[0] & ~x;
  assign next_state[1] = (state[0] & x) | state[1];

  assign z = (state[0] & x) | (state[1] & ~x);

  always @(posedge clk or posedge areset) begin
    if (areset) begin
      state <= 2'b01; // Reset to state A
    end else begin
