  // Output is 1 for state D (one-hot bit 3)
  assign out = state[3];

  // Combinational next-state logic for one-hot encoding:
  // A = state[0], B = state[1], C = state[2], D = state[3]
  always @* begin
    next_state = { (in & state[2]),                     // D <- C when in==1
                   (~in & (state[1] | state[3])),       // C <- B or D when in==0
                   (in & (state[0] | state[1] | state[3])), // B <- A,B,D when in==1
                   (~in & (state[0] | state[2])) };     // A <- A or C when in==0
  end
