  // States
  localparam S0 = 0;
  localparam S1 = 1;
  localparam S2 = 2;
  localparam S3 = 3;
  localparam S4 = 4;
  localparam S5 = 5;
  localparam S6 = 6;
  localparam S_err = 7;
  localparam St_disc = 8;
  localparam St_flag = 9;

  reg [3:0] state, next_state;

  // State register
  always @(posedge clk) begin
    if (reset)
      state <= S0;
    else
      state <= next_state;
  end

  // Next state logic
  always @(*) begin
    case (state)
      S0: next_state = in ? S1 : S0;
      S1: next_state = in ? S2 : S0;
      S2: next_state = in ? S3 : S0;
      S3: next_state = in ? S4 : S0;
      S4: next_state = in ? S5 : S0;
      S5: next_state = in ? S6 : St_disc;
      S6: next_state = in ? S_err : St_flag;
      S_err: next_state = in ? S_err : S0;
      St_disc: next_state = in ? S1 : S0;
      St_flag: next_state = in ? S1 : S0;
      default: next_state = S0;
    endcase
  end

  // Output logic (Moore)
  assign disc = (state == St_disc);
  assign flag = (state == St_flag);
  assign err = (state == S_err);

endmodule

