module TopModule (
    input clk,
    input [7:0] in,
    input reset,
    output done
);
    parameter IDLE   = 2'b00;
    parameter FIRST  = 2'b01;
    parameter SECOND = 2'b10;

    reg [1:0] state;
    reg done_reg;

    assign done = done_reg;

    always @(posedge clk) begin
        if (reset) begin
            state <= IDLE;
            done_reg <= 1'b0;
        end else begin
            // Clear done pulse each cycle
            done_reg <= 1'b0;
            case (state)
                IDLE: begin
                    if (in[3]) begin
                        state <= FIRST;
                    end
                end
                FIRST: begin
                    state <= SECOND;
                end
                SECOND: begin
                    // Third byte received, assert done and return to IDLE
                    state <= IDLE;
                    done_reg <= 1'b1;
                end
                default: begin
                    state <= IDLE;
                end
            endcase
        end
    end
endmodule

module TopModule (
  input clk,
  input in,
  input reset,
  output done
);

  reg [1:0] state;
  reg [2:0] bit_count;
  reg done_reg;

  localparam IDLE  = 2'b00;
  localparam DATA  = 2'b01;
  localparam STOP  = 2'b10;
  localparam ERROR = 2'b11;

  assign done = done_reg;

  always @(posedge clk) begin
    if (reset) begin
      state <= IDLE;
      bit_count <= 3'b0;
      done_reg <= 1'b0;
    end else begin
      done_reg <= 1'b0;
      case (state)
        IDLE: begin
          if (in == 1'b0) begin
            state <= DATA;
            bit_count <= 3'b0;
          end
        end
        DATA: begin
          if (bit_count == 3'b111) begin
            state <= STOP;
          end
          bit_count <= bit_count + 1;
        end
        STOP: begin
          if (in == 1'b1) begin
            state <= IDLE;
            done_reg <= 1'b1;
          end else begin
            state <= ERROR;
          end
        end
        ERROR: begin
          if (in == 1'b1) begin
            state <= IDLE;
          end
        end
      endcase
    end
  end

endmodule

module TopModule (
