module TopModule (
  input clk,
  input areset,
  input bump_left,
  input bump_right,
  output walk_left,
  output walk_right
);

  reg state;

  localparam LEFT = 1'b0;
  localparam RIGHT = 1'b1;

  always @(posedge clk or posedge areset) begin
    if (areset)
      state <= LEFT;
    else begin
      case (state)
        LEFT:  state <= bump_left ? RIGHT : LEFT;
        RIGHT: state <= bump_right ? LEFT : RIGHT;
      endcase
    end
  end

  assign walk_left = (state == LEFT);
  assign walk_right = (state == RIGHT);

endmodule

module TopModule (
    input clk,
    input areset,
    input bump_left,
    input bump_right,
    input ground,
    output walk_left,
    output walk_right,
    output aaah
);

    // State encoding: WL=0, WR=1, FL=2, FR=3
    reg [1:0] state;
    reg [1:0] next_state;

    // State definitions
    localparam WL = 2'b00;
    localparam WR = 2'b01;
    localparam FL = 2'b10;
    localparam FR = 2'b11;

    // Next state logic
    always @(*) begin
        case (state)
            WL: next_state = ground ? (bump_left ? WR : WL) : FL;
            WR: next_state = ground ? (bump_right ? WL : WR) : FR;
            FL: next_state = ground ? WL : FL;
            FR: next_state = ground ? WR : FR;
            default: next_state = WL;
        endcase
    end

    // Sequential logic
    always @(posedge clk or posedge areset) begin
        if (areset)
            state <= WL;
        else
            state <= next_state;
    end

    // Output logic (Moore style: outputs depend only on state)
    assign walk_left  = (state == WL);
    assign walk_right = (state == WR);
    assign aaah       = (state == FL || state == FR);

endmodule

module TopModule (
  input x,
  input y,
  output z
);

  // Internal wires to represent the outputs of the submodule logic
  // and the intermediate logic gates.
  wire a_out;   // Output of an A submodule
  wire b_out;   // Output of a B submodule
  wire or_out;  // Output of the OR gate
  wire and_out; // Output of the AND gate

  // Logic for Module A: z = (x^y) & x
  // The two A submodules have the same inputs, so their outputs are identical.
  assign a_out = (x ^ y) & x;

  // Logic for Module B: z = x~^y (XNOR), derived from the waveform
  // The two B submodules also have identical inputs and thus identical outputs.
  assign b_out = x ~^ y;

  // The first pair (A1, B1) goes into an OR gate
  assign or_out = a_out | b_out;

  // The second pair (A2, B2) goes into an AND gate
  assign and_out = a_out & b_out;

  // The final output is the XOR of the OR and AND outputs
  assign z = or_out ^ and_out;

endmodule

module TopModule (
  input clk,
  input reset,
  input data,
  output start_shifting
);

reg [3:0] shift_reg;
reg start_shifting_reg;

assign start_shifting = start_shifting_reg;

always @(posedge clk) begin
  if (reset) begin
    shift_reg <= 4'b0000;
    start_shifting_reg <= 1'b0;
  end else begin
    shift_reg <= {shift_reg[2:0], data};
    if ({shift_reg[2:0], data} == 4'b1101)
      start_shifting_reg <= 1'b1;
  end
end

endmodule

module TopModule (
    input clk,
    input reset,
    output shift_ena
);

reg [3:0] shift_reg;

always @(posedge clk) begin
    if (reset)
        shift_reg <= 4'b1111;
    else
        shift_reg <= {1'b0, shift_reg[3:1]};
end

assign shift_ena = |shift_reg;

endmodule

module TopModule (
  input x3,
  input x2,
  input x1,
  output f
);
  assign f = x3 ? x1 : x2;
endmodule

module TopModule (
  input [3:0] x,
  output logic f
);
  assign f = (!x[3] & !x[1]) | (x[2] & !x[0]) | (x[2] & x[3] & x[1]);
endmodule

module TopModule (
  input clk,
  input resetn,
  input x,
  input y,
  output f,
  output g
);

parameter A      = 4'd0;
parameter F      = 4'd1;
parameter WAITX0 = 4'd2;
parameter WAITX1 = 4'd3;
parameter WAITX10= 4'd4;
parameter G0     = 4'd5;
parameter G1     = 4'd6;
parameter LOCK1  = 4'd7;
parameter LOCK0  = 4'd8;

reg [3:0] state;

always @(posedge clk) begin
  if (!resetn) begin
    state <= A;
  end else begin
    case (state)
      A: begin
        state <= F;
      end

      F: begin
        state <= WAITX0;
      end

      WAITX0: begin
        if (x == 1'b1)
          state <= WAITX1;
        else
          state <= WAITX0;
      end

      WAITX1: begin
        if (x == 1'b0)
          state <= WAITX10;
        else if (x == 1'b1)
          state <= WAITX1; // treat as new start
        else
          state <= WAITX0;
      end

      WAITX10: begin
        if (x == 1'b1)
          state <= G0; // pattern detected
        else if (x == 1'b0)
          state <= WAITX0; // pattern broken
        else
          state <= WAITX10;
      end

      G0: begin
        if (y == 1'b1)
          state <= LOCK1;
        else
          state <= G1;
      end

      G1: begin
        if (y == 1'b1)
          state <= LOCK1;
        else
          state <= LOCK0;
      end

      LOCK1: begin
        state <= LOCK1;
      end

      LOCK0: begin
        state <= LOCK0;
      end

      default: state <= A;
    endcase
  end
end

assign f = (state == F);
assign g = (state == G0 || state == G1 || state == LOCK1);

endmodule

module TopModule (
  input clock,
  input a,
  output reg p,
  output reg q
);

// p is a level-sensitive latch: follows a when clock=1
always @(clock or a) begin
  if (clock) p = a;
  // No else clause, so p will latch its value when clock=0
end

// q captures the value of p on the falling edge of the clock
always @(negedge clock) begin
  q <= p;
end

endmodule

module TopModule (
    input clk,
    input x,
    output z
);

    reg Q1 = 0, Q2 = 0, Q3 = 0;

    always @(posedge clk) begin
        Q1 <= x ^ Q1;
        Q2 <= x & ~Q2;
        Q3 <= x | ~Q3;
    end

    assign z = ~(Q1 | Q2 | Q3);

endmodule

module TopModule (
  input clk,
  input areset,
  input x,
  output z
);
  reg last;
  reg seen_one;

  // State update: last holds the most recently sampled input bit,
  // seen_one indicates whether any lower-significance bit (already processed)
  // was '1'. Both registers are updated on the clock edge (async reset).
  always @(posedge clk or posedge areset) begin
    if (areset) begin
      last <= 1'b0;
      seen_one <= 1'b0;
    end else begin
      last <= x;
      seen_one <= seen_one | last;
    end
  end

  // Moore output: determined solely by the state (seen_one and last).
  // If we have not yet seen a '1', copy the bit; after the first '1',
  // invert the remaining bits (this implements serial 2's-complement).
  assign z = seen_one ? ~last : last;

endmodule

module TopModule (
  input clk,
  input reset,
  output reg [4:0] q
);
always @(posedge clk) begin
  if (reset)
    q <= 5'b00001;
  else
    q <= {q[0], q[4], q[3] ^ q[0], q[2], q[1]};
end
endmodule

module TopModule (
