endmodule

module TopModule (
  input [2:0] y,
  input w,
  output reg Y1
);
  always @(*) begin
    Y1 = (~y[1] & y[0]) | (~y[0] & w & (y[2] ^ y[1]));
  end
endmodule

module TopModule (
  input d,
  input done_counting,
  input ack,
  input [9:0] state, // 10-bit one-hot current state
  output B3_next,
  output S_next,
  output S1_next,
  output Count_next,
  output Wait_next,
  output done,
  output counting,
  output shift_ena
);

  // State encoding (one-hot):
  // state[0] = S
  // state[1] = S1
  // state[2] = S11
  // state[3] = S110
  // state[4] = B0
  // state[5] = B1
  // state[6] = B2
  // state[7] = B3
  // state[8] = Count
  // state[9] = Wait

  // Next-state logic (combinational)
  assign B3_next  = state[6]; // B2 -> B3

  // S_next: from S (d=0), S1 (d=0), S110 (d=0), or Wait (ack=1)
  assign S_next   = (~d & (state[0] | state[1] | state[3])) | (state[9] & ack);

  // S1_next: from S (d=1)
  assign S1_next  = d & state[0];

  // Count_next: from B3 or Count (done_counting=0)
  assign Count_next = state[7] | (state[8] & ~done_counting);

  // Wait_next: from Count (done_counting=1) or Wait (ack=0)
  assign Wait_next  = (state[8] & done_counting) | (state[9] & ~ack);

  // Output logic (Moore outputs depend on current state)
  assign done      = state[9];
  assign counting  = state[8];
  assign shift_ena = state[4] | state[5] | state[6] | state[7];

endmodule

module adder_32bit(A, B, S, C32);
    input [32:1] A;
    input [32:1] B;
    output [32:1] S;
    output C32;

    wire C16;

    cla_16bit cla0(
        .A(A[16:1]),
        .B(B[16:1]),
        .Cin(1'b0),
        .S(S[16:1]),
        .Cout(C16)
    );

    cla_16bit cla1(
        .A(A[32:17]),
        .B(B[32:17]),
        .Cin(C16),
        .S(S[32:17]),
        .Cout(C32)
    );

endmodule

module cla_16bit(A, B, Cin, S, Cout);
    input [16:1] A;
    input [16:1] B;
    input Cin;
    output [16:1] S;
    output Cout;

    wire C4, C8, C12;
    wire PG0, GG0, PG1, GG1, PG2, GG2, PG3, GG3;

    cla_4bit cla0(
        .A(A[4:1]),
        .B(B[4:1]),
        .Cin(Cin),
        .S(S[4:1]),
        .PG(PG0),
        .GG(GG0)
    );

    cla_4bit cla1(
        .A(A[8:5]),
        .B(B[8:5]),
        .Cin(C4),
        .S(S[8:5]),
        .PG(PG1),
        .GG(GG1)
    );

    cla_4bit cla2(
        .A(A[12:9]),
        .B(B[12:9]),
        .Cin(C8),
        .S(S[12:9]),
        .PG(PG2),
        .GG(GG2)
    );

    cla_4bit cla3(
        .A(A[16:13]),
        .B(B[16:13]),
        .Cin(C12),
        .S(S[16:13]),
        .PG(PG3),
        .GG(GG3)
    );

    // Second-level carry lookahead
    assign C4  = GG0 | (PG0 & Cin);
    assign C8  = GG1 | (PG1 & GG0) | (PG1 & PG0 & Cin);
    assign C12 = GG2 | (PG2 & GG1) | (PG2 & PG1 & GG0) | (PG2 & PG1 & PG0 & Cin);
    assign Cout = GG3 | (PG3 & GG2) | (PG3 & PG2 & GG1) | (PG3 & PG2 & PG1 & GG0) | (PG3 & PG2 & PG1 & PG0 & Cin);

endmodule

module cla_4bit(A, B, Cin, S, PG, GG);
    input [4:1] A;
    input [4:1] B;
    input Cin;
    output [4:1] S;
    output PG;
    output GG;

    wire [4:1] G, P;
    wire [4:0] C;

    assign G = A & B;
    assign P = A ^ B;
    assign C[0] = Cin;

    // Carry lookahead logic
    assign C[1] = G[1] | (P[1] & C[0]);
    assign C[2] = G[2] | (P[2] & G[1]) | (P[2] & P[1] & C[0]);
    assign C[3] = G[3] | (P[3] & G[2]) | (P[3] & P[2] & G[1]) | (P[3] & P[2] & P[1] & C[0]);
    assign C[4] = G[4] | (P[4] & G[3]) | (P[4] & P[3] & G[2]) | (P[4] & P[3] & P[2] & G[1]) | (P[4] & P[3] & P[2] & P[1] & C[0]);

    assign S = P ^ C[3:0];

    // Group propagate and generate
    assign PG = P[4] & P[3] & P[2] & P[1];
    assign GG = G[4] | (P[4] & G[3]) | (P[4] & P[3] & G[2]) | (P[4] & P[3] & P[2] & G[1]);

endmodule

module adder_8bit(
    input [7:0] a, b, 
    input cin, 
    output [7:0] sum, 
    output cout);

    wire [7:0] carry;

    // Full adder for bit 0
    assign {carry[0], sum[0]} = a[0] + b[0] + cin;

    // Full adder for bits 1-7
    genvar i;
    generate
        for (i = 1; i < 8; i = i + 1) begin : full_adder_loop
            assign {carry[i], sum[i]} = a[i] + b[i] + carry[i-1];
        end
    endgenerate

    assign cout = carry[7];

endmodule

module adder_bcd (
    input  [3:0] A,   // First BCD number (0-9)
    input  [3:0] B,   // Second BCD number (0-9)
    input  Cin,       // Input carry
    output [3:0] Sum, // BCD sum (0-9)
    output Cout       // Output carry
);

    wire [3:0] binary_sum;
    wire [4:0] temp_sum;
    wire correction_needed;

    assign temp_sum = A + B + Cin;
    assign binary_sum = temp_sum[3:0];

    assign correction_needed = (temp_sum > 5'd9) ? 1'b1 : 1'b0;

    assign Sum = correction_needed ? (binary_sum + 4'd6) : binary_sum;
    assign Cout = correction_needed;

endmodule

module comparator_3bit (
    input [2:0] A,
    input [2:0] B,
    output A_greater,
    output A_equal,
    output A_less
);

    assign A_greater = (A > B);
    assign A_equal   = (A == B);
    assign A_less    = (A < B);

endmodule

module comparator_4bit(
    input [3:0] A,
    input [3:0] B,
    output A_greater,
    output A_equal,
    output A_less
);

    wire [3:0] diff;
    wire borrow;

    assign {borrow, diff} = A - B;

    assign A_greater = (borrow == 1'b0) && (diff != 4'b0000);
    assign A_equal = (diff == 4'b0000);
    assign A_less = (borrow == 1'b1);

endmodule

module counter_12 
(
  input rst_n,
  input clk,
  input valid_count,

  output reg [3:0] out
);

always @(posedge clk or negedge rst_n) begin
  if (!rst_n)
    out <= 4'b0000;
  else if (valid_count) begin
    if (out == 4'd11)
      out <= 4'b0000;
    else
      out <= out + 4'b0001;
  end
  else
    out <= out;
end

endmodule

module edge_detect(
	input clk,
	input rst_n,
	input a,

	output reg rise,
	output reg down
);

reg a_dly;

always @(posedge clk or negedge rst_n) begin
	if (!rst_n) begin
		a_dly <= 1'b0;
		rise  <= 1'b0;
		down  <= 1'b0;
	end else begin
		rise  <= (~a_dly) & a;
		down  <= a_dly & (~a);
		a_dly <= a;
	end
end

endmodule

module freq_divbyeven(
    clk,
    rst_n,
    clk_div
);
    input clk;
    input rst_n;
    output clk_div;
    reg clk_div;

    parameter NUM_DIV = 6;

    reg [3:0] cnt;

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            cnt <= 4'd0;
            clk_div <= 1'b0;
        end else begin
            if (cnt < (NUM_DIV/2 - 1))
                cnt <= cnt + 4'd1;
            else begin
                cnt <= 4'd0;
                clk_div <= ~clk_div;
            end
        end
    end

endmodule

module instr_reg (
    input clk,
    input rst,
    input [1:0] fetch,
    input [7:0] data,
    output [2:0] ins,
    output [4:0] ad1,
    output [7:0] ad2
);

    reg [7:0] ins_p1;
    reg [7:0] ins_p2;

    always @(posedge clk) begin
        if (!rst) begin
            ins_p1 <= 8'b0;
            ins_p2 <= 8'b0;
        end else begin
            case (fetch)
                2'b01: ins_p1 <= data;
                2'b10: ins_p2 <= data;
                default: begin
                    // Keep previous values
                end
            endcase
        end
    end

    assign ins = ins_p1[7:5];
    assign ad1 = ins_p1[4:0];
    assign ad2 = ins_p2;

endmodule

module LFSR (out, clk, rst);
  input clk, rst;
  output reg [3:0] out;

  wire feedback;

  assign feedback = ~(out[3] ^ out[2]);

  always @(posedge clk) begin
    if (rst)
      out <= 4'b0000;
    else
      out <= {out[2:0], feedback};
  end

endmodule

module right_shifter(clk, q,d);  

    input  clk;  
    input d;  
    output  [7:0] q;

    reg [7:0] q;

    initial begin
        q = 8'b0;
    end

    always @(posedge clk) begin
        q <= {d, q[7:1]};
    end

endmodule

module synchronizer(
	input 				clk_a	, 
	input 				clk_b	,   
	input 				arstn	,
	input				brstn   ,
	input		[3:0]	data_in	,
	input               data_en ,

	output reg  [3:0] 	dataout
);

    reg [3:0] data_reg;
    reg en_data_reg;
    reg en_clap_one, en_clap_two;
    reg [3:0] dataout_next;

    always @(posedge clk_a or negedge arstn) begin
        if (!arstn) begin
            data_reg <= 4'b0;
            en_data_reg <= 1'b0;
        end else begin
            data_reg <= data_in;
            en_data_reg <= data_en;
        end
    end

    always @(posedge clk_b or negedge brstn) begin
        if (!brstn) begin
            en_clap_one <= 1'b0;
            en_clap_two <= 1'b0;
        end else begin
            en_clap_one <= en_data_reg;
            en_clap_two <= en_clap_one;
        end
    end

    always @(posedge clk_b or negedge brstn) begin
        if (!brstn) begin
            dataout <= 4'b0;
        end else begin
            if (en_clap_two) begin
                dataout <= data_reg;
            end
        end
    end

endmodule

module fsm(IN,MATCH,CLK,RST);
input IN,CLK,RST;
output reg MATCH;

reg [2:0] state, next_state;

parameter S0 = 3'b000;
parameter S1 = 3'b001;
parameter S2 = 3'b010;
parameter S3 = 3'b011;
parameter S4 = 3'b100;

always @(posedge CLK or posedge RST) begin
    if (RST) begin
        state <= S0;
        MATCH <= 1'b0;
    end
    else begin
        state <= next_state;
        case (next_state)
            S4: MATCH <= (IN == 1'b1) ? 1'b1 : 1'b0;
            default: MATCH <= 1'b0;
        endcase
    end
end

always @(state or IN) begin
    case (state)
        S0: next_state = (IN == 1'b1) ? S1 : S0;
        S1: next_state = (IN == 1'b0) ? S2 : S1;
        S2: next_state = (IN == 1'b0) ? S3 : (IN == 1'b1) ? S1 : S0;
        S3: next_state = (IN == 1'b1) ? S4 : S0;
        S4: next_state = (IN == 1'b1) ? S1 : S2;
        default: next_state = S0;
    endcase
end

endmodule

module parallel2serial(
    input clk,
    input rst_n,
    input [3:0] d,
    output valid_out,
    output dout
);

    reg [1:0] cnt;
    reg [3:0] data;
    reg valid;

    assign valid_out = valid;
    assign dout = data[3];

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            cnt <= 2'b0;
            data <= 4'b0;
            valid <= 1'b0;
        end else begin
            if (cnt == 2'b11) begin
                data <= d;
                cnt <= 2'b0;
                valid <= 1'b1;
            end else begin
                data <= {data[2:0], 1'b0};
                cnt <= cnt + 1'b1;
                valid <= 1'b0;
            end
        end
    end

endmodule

module ROM (
    input wire [7:0] addr,        // 8-bit Address input
    output reg [15:0] dout        // 16-bit Data output
);

    reg [15:0] mem [0:255];

    initial begin
        mem[0] = 16'hA0A0;
        mem[1] = 16'hB1B1;
        mem[2] = 16'hC2C2;
        mem[3] = 16'hD3D3;
    end

    always @(*) begin
        dout = mem[addr];
    end

endmodule

module sequence_detector(
     input  clk, 
     input  rst_n,
     input  data_in, 
     output sequence_detected				
     );

    // State encoding
    parameter IDLE = 3'd0;
    parameter S1   = 3'd1;
    parameter S2   = 3'd2;
    parameter S3   = 3'd3;
    parameter S4   = 3'd4;

    reg [2:0] current_state, next_state;

    // State register
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n)
            current_state <= IDLE;
        else
            current_state <= next_state;
    end

    // Next state logic
    always @(*) begin
        case (current_state)
            IDLE: begin
                if (data_in == 1'b1)
                    next_state = S1;
                else
                    next_state = IDLE;
            end
            S1: begin
                if (data_in == 1'b0)
                    next_state = S2;
                else
                    next_state = S1;
            end
            S2: begin
                if (data_in == 1'b0)
                    next_state = S3;
                else
                    next_state = S1;
            end
            S3: begin
                if (data_in == 1'b1)
                    next_state = S4;
                else
                    next_state = IDLE;
            end
            S4: begin
                if (data_in == 1'b1)
                    next_state = S1;
                else
                    next_state = IDLE;
            end
            default: begin
                next_state = IDLE;
            end
        endcase
    end

    // Output logic
    assign sequence_detected = (current_state == S4);

endmodule
